	token, err = exchangeJurisdictionToken(ctx, exchangeCore, subjectToken, audience, httpClient)
	if err != nil {
		return "", "", "", fmt.Errorf("exchange jurisdictional identity token: %w", err)
	}
	return token, audience, exchangeCore, nil
}

