255	// environment family and loopback detection), the data origin the CLI is pointed
256	// at (audience/cell fallback), and the HTTP client to use for the exchange (and
257	// any cluster listing).
258	type cellSubject struct {
259		loginJWT       string
260		discoveredCore string
261		dataOrigin     string
262		httpClient     *http.Client
263	}
264	
265	// resolveCellSubject picks the jurisdiction-exchange subject: ENTIRE_TOKEN when
266	// set (exclusive, fail-closed), otherwise the active stored login context. This
267	// is the ENTIRE_TOKEN-aware dispatcher used by JurisdictionToken;
268	// NewEntireAPICellClient calls resolveStoredCellSubject directly so its behavior
269	// is unchanged.
270	func resolveCellSubject(ctx context.Context, insecureHTTP bool) (cellSubject, error) {
271		if raw, ok := os.LookupEnv(EnvTokenVar); ok {
272			return resolveEnvTokenCellSubject(raw, insecureHTTP)
273		}
274		return resolveStoredCellSubject(ctx, insecureHTTP)
275	}
276	
277	// resolveStoredCellSubject resolves the exchange subject from the active stored
278	// login context: it discovers the data host's trusted login servers and
279	// mints/refreshes the context's login JWT.
280	func resolveStoredCellSubject(ctx context.Context, insecureHTTP bool) (cellSubject, error) {
281		dataURL := api.BaseURL()
282		if insecureHTTP {
283			EnableInsecureHTTP()
284		} else if err := api.RequireSecureURL(dataURL); err != nil {
285			return cellSubject{}, fmt.Errorf("base URL check: %w", err)
286		}
287	
288		dataOrigin := api.OriginOnly(dataURL)
289		host, ok := hostOf(dataOrigin)
290		if !ok {
291			return cellSubject{}, fmt.Errorf("data API URL %q has no host to discover against", dataURL)
292		}
293	
294		dctx, cancel := context.WithTimeout(ctx, dataAPIDiscoveryTimeout)
295		defer cancel()
296		httpClient := cellExchangeHTTPClient(dataOrigin)
297	
298		selected, err := resolveContextForCellAPI(dctx, userdirs.Config(), userdirs.Cache(), host, httpClient, nil)
299		if errors.Is(err, clusterdiscovery.ErrDiscoveryUnavailable) {
300			return cellSubject{}, fmt.Errorf("%s does not advertise its trusted login servers (/.well-known/entire-api.json missing or unreachable); cannot authenticate: %w", host, err)
301		}
302		if err != nil {
303			return cellSubject{}, err
304		}
305	
306		// Gate the login provider's HTTPS relaxation on the core it actually dials
307		// (selected.CoreURL) plus the explicit --insecure-http-auth opt-in, matching
308		// the sibling ResolveDataAPIToken. A loopback data API must not relax HTTPS
309		// for a non-loopback core.
310		allowInsecure := insecureHTTPEnabled() || isLoopbackHTTP(selected.CoreURL)
311		loginProvider, err := NewRefreshingLoginProvider(selected, cellExchangeTransportForTest, allowInsecure)
312		if err != nil {
313			return cellSubject{}, err
314		}
315	
316		loginJWT, err := loginProvider(ctx)
317		if err != nil {
318			if errors.Is(err, ErrNotLoggedIn) {
319				return cellSubject{}, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
320			}
321			// The provider already prefixes "refresh login token:"; return as-is to
322			// avoid a doubled prefix.
323			return cellSubject{}, err
324		}
325	
326		return cellSubject{
327			loginJWT:       loginJWT,
328			discoveredCore: selected.CoreURL,
329			dataOrigin:     dataOrigin,
